  let currentLang = "hindi";

  function updateCardContents(language) {
    currentLang = language;
    const cards = document.querySelectorAll(".utility-card");
    const langData = itemsData[language] || itemsData["hindi"];
    const langAudio = audioData[language] || audioData["hindi"];
    const isRtl = language === "urdu";

    cards.forEach((card, index) => {
      const item = langData[index];
      if (item) {
        const h2 = card.querySelector("h2");
        const badge = card.querySelector(".badge-acq");
        const p = card.querySelector("p");

        if (h2) h2.textContent = item.title;
        if (badge) badge.textContent = item.badge;
        if (p) p.innerHTML = item.desc.split("\n\n").join("<br><br>");

        [h2, badge, p].forEach((el) => {
          if (!el) return;
          if (isRtl) {
            el.setAttribute("dir", "rtl");
            el.style.textAlign = "right";
          } else {
            el.removeAttribute("dir");
            el.style.textAlign = el === p ? "justify" : "left";
          }
        });
      }

      const audioPlayer = card.querySelector("audio.card-audio");
      const rawAudioSrc = (langAudio && langAudio[index]) ? langAudio[index] : (audioData["hindi"] ? audioData["hindi"][index] : null);
      if (audioPlayer) {
        if (rawAudioSrc) {
          const safeSrc = encodeURI(rawAudioSrc);
          if (audioPlayer.getAttribute("src") !== safeSrc) {
            audioPlayer.pause();
            audioPlayer.src = safeSrc;
            audioPlayer.load();
          }

          audioPlayer.onerror = () => {
            console.warn("Audio file failed to load, TTS fallback available for:", rawAudioSrc);
          };
        } else {
          audioPlayer.removeAttribute("src");
          audioPlayer.load();
        }
      }
    });
  }

  function speakCardText(card) {
    if (!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();

    const h2 = card.querySelector("h2");
    const p = card.querySelector("p");
    const textToSpeak = `${h2 ? h2.textContent : ''}. ${p ? p.textContent : ''}`;

    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    utterance.lang = langVoiceMap[currentLang] || "hi-IN";
    utterance.rate = 0.95;
    window.speechSynthesis.speak(utterance);
  }

